// Tag every element created by this script so we can suppress only our own overlapping panels
(function() {
  const orig = document.createElement;
  document.createElement = function(tag) {
    const el = orig.apply(this, arguments);
    try { el.setAttribute("data-zhen-script", "1"); } catch(e) {}
    return el;
  };
  // Restore after a generous delay (main UI creation finishes early)
  setTimeout(() => { document.createElement = orig; }, 8000);
})();



